const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
    const l = parseInt(input[0], 10);
    const str = input[1];

    let fsCount = 0;
    let sfCount = 0;

    for (let i = 0; i < str.length - 1; i++) {
        if (str[i] === 'F' && str[i + 1] === 'S') {
            fsCount++;
        }
        if (str[i] === 'S' && str[i + 1] === 'F') {
            sfCount++;
        }
    }

    if (sfCount > fsCount) {
        console.log("YES");
    } else {
        console.log("NO");
    }
}

main();
