const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

rl.on('line', (line) => {
    const parts = line.trim().split(/\s+/);
    const l = parseInt(parts[0], 10);
    const str = parts[1];

    const countSubstr = (str, sub) => {
        let count = 0;
        let idx = 0;
        while ((idx = str.indexOf(sub, idx)) !== -1) {
            count++;
            idx += sub.length;
        }
        return count;
    };

    const fs = countSubstr(str, "FS");
    const sf = countSubstr(str, "SF");

    if (sf > fs) {
        console.log("YES");
    } else {
        console.log("NO");
    }
});
