const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const input = lines.join(' ');
    const parts = input.split(/\s+/).filter(part => part.length > 0);
    const l = parseInt(parts[0], 10);
    const str = parts[1] || '';

    function countOccurrences(str, sub) {
        let count = 0;
        let idx = 0;
        while ((idx = str.indexOf(sub, idx)) !== -1) {
            count++;
            idx += sub.length;
        }
        return count;
    }

    const fs = countOccurrences(str, "FS");
    const sf = countOccurrences(str, "SF");

    if (sf > fs) {
        console.log("YES");
    } else {
        console.log("NO");
    }
});
